--

CREATE TABLE public.posthog_task (
    id uuid NOT NULL,
    title character varying(255) NOT NULL,
    description text NOT NULL,
    origin_product character varying(20) NOT NULL,
    "position" integer,
    repository_config jsonb,
    github_branch character varying(255),
    github_pr_url character varying(200),
    created_at timestamp with time zone NOT NULL,
    updated_at timestamp with time zone NOT NULL,
    github_integration_id integer,
    team_id integer NOT NULL,
    current_stage_id uuid,
    workflow_id uuid,
    task_number integer,
    created_by_id integer,
    json_schema jsonb,
    repository character varying(255),
    deleted boolean,
    deleted_at timestamp with time zone,
    title_manually_set boolean NOT NULL,
    internal boolean NOT NULL,
    signal_report_id uuid,
    ci_prompt text,
    github_user_integration_id uuid,
    archived boolean NOT NULL,
    archived_at timestamp with time zone,
    channel_id uuid,
    state jsonb,
    runtime character varying(10) DEFAULT 'acp'::character varying NOT NULL,
    loop_id uuid,
    repositories character varying(255)[] DEFAULT '{}'::character varying(255)[] NOT NULL,
    client_provenance character varying(32)
);


