    web_analytics_pre_aggregated_tables_enabled boolean,
    web_analytics_pre_aggregated_tables_version character varying(10),
    experiment_recalculation_time time without time zone,
    default_evaluation_environments_enabled boolean,
    receive_org_level_activity_logs boolean,
    business_model character varying(10),
    require_evaluation_environment_tags boolean,
    product_tours_opt_in boolean,
    conversations_enabled boolean,
    conversations_settings jsonb,
    logs_settings jsonb,
