    default_experiment_stats_method character varying(20),
    proactive_tasks_enabled boolean,
    session_recording_trigger_groups jsonb,
    llm_gateway_revoked_at timestamp with time zone,
    llm_gateway_enabled_at timestamp with time zone,
    ingested_production_event boolean DEFAULT false NOT NULL,
    ingested_production_event_last_checked_at timestamp with time zone,
    llm_gateway_overspend_allowance_usd numeric(20,6),
    event_retention_months smallint DEFAULT 84 NOT NULL,
    CONSTRAINT llm_gateway_overspend_allowance_usd_in_range CHECK (((llm_gateway_overspend_allowance_usd IS NULL) OR ((llm_gateway_overspend_allowance_usd >= (0)::numeric) AND (llm_gateway_overspend_allowance_usd <= (10000)::numeric)))),
    CONSTRAINT posthog_team_event_retention_months_check CHECK ((event_retention_months >= 0)),
    CONSTRAINT project_id_is_not_null CHECK ((project_id IS NOT NULL))
);


