--
-- Name: reminders_reminder; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.reminders_reminder (
    created_at timestamp with time zone NOT NULL,
    updated_at timestamp with time zone,
    id uuid NOT NULL,
    title character varying(255) NOT NULL,
    message text NOT NULL,
    resource_type character varying(50),
    resource_id character varying(200),
    scheduled_at timestamp with time zone,
    recurrence_interval character varying(20),
    cron_expression character varying(100),
    timezone character varying(64) NOT NULL,
    end_date timestamp with time zone,
    next_fire_at timestamp with time zone,
    last_fired_at timestamp with time zone,
    failure_count integer NOT NULL,
    last_error text,
    status character varying(20) NOT NULL,
    deleted boolean NOT NULL,
    created_by_id integer,
    organization_id uuid NOT NULL,
    team_id integer,
    CONSTRAINT reminders_schedule_exactly_one CHECK ((((cron_expression IS NULL) AND (recurrence_interval IS NULL) AND (scheduled_at IS NOT NULL)) OR ((cron_expression IS NULL) AND (recurrence_interval IS NOT NULL) AND (scheduled_at IS NULL)) OR ((cron_expression IS NOT NULL) AND (recurrence_interval IS NULL) AND (scheduled_at IS NULL))))
);


--
-- Name: replay_vision_replayobservation; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.replay_vision_replayobservation (
    id uuid NOT NULL,
    session_id character varying(200) NOT NULL,
    status character varying(16) NOT NULL,
    error_reason text NOT NULL,
    workflow_id character varying(255) NOT NULL,
    triggered_by character varying(16) NOT NULL,
    started_at timestamp with time zone,
    completed_at timestamp with time zone,
    created_at timestamp with time zone NOT NULL,
