    team_id integer NOT NULL,
    triggered_by_user_id integer,
    scanner_snapshot jsonb NOT NULL,
    scanner_result jsonb NOT NULL,
    distinct_id character varying(400),
    session_started_at timestamp with time zone,
    recording_subject_email text,
    created_task_id uuid,
    backfill_id uuid,
    session_group_keys jsonb,
    CONSTRAINT replay_observation_completed_at_matches_status CHECK ((((completed_at IS NULL) AND ((status)::text = ANY ((ARRAY['pending'::character varying, 'running'::character varying])::text[]))) OR ((completed_at IS NOT NULL) AND ((status)::text = ANY ((ARRAY['succeeded'::character varying, 'failed'::character varying, 'ineligible'::character varying])::text[])))))
);


