    provider character varying(32) NOT NULL,
    model character varying(64) NOT NULL,
    emits_signals boolean NOT NULL,
    scanner_version integer NOT NULL,
    last_swept_at timestamp with time zone NOT NULL,
    created_at timestamp with time zone NOT NULL,
    updated_at timestamp with time zone NOT NULL,
    created_by_id integer,
    team_id integer NOT NULL,
    enabled boolean NOT NULL,
    last_seen_session_id character varying(200) DEFAULT ''::character varying NOT NULL,
    estimated_at timestamp with time zone,
    estimated_monthly_observations integer,
    sampling_mode character varying(20) NOT NULL,
    feedback_themes jsonb,
    origin character varying(16) DEFAULT 'configured'::character varying NOT NULL,
    inline_key character varying(64) DEFAULT ''::character varying NOT NULL,
    experiment_targeting jsonb,
    last_deep_swept_at timestamp with time zone,
    credit_limit integer,
    sweep_read_bytes_by_hour jsonb,
    sweep_throttle_factor_override smallint,
    limit_notified_period_start timestamp with time zone,
    CONSTRAINT replay_scanner_credit_limit_positive CHECK (((credit_limit IS NULL) OR (credit_limit >= 1))),
    CONSTRAINT replay_scanner_inline_key_matches_origin CHECK (((((inline_key)::text = ''::text) AND ((origin)::text = 'configured'::text)) OR (((origin)::text = 'inline'::text) AND (NOT ((inline_key)::text = ''::text))))),
    CONSTRAINT replay_scanner_sampling_rate_range CHECK (((sampling_rate >= (0.0)::double precision) AND (sampling_rate <= (1.0)::double precision))),
    CONSTRAINT replay_vision_replaylens_lens_version_check CHECK ((scanner_version >= 0)),
    CONSTRAINT replay_vision_replayscanner_credit_limit_check CHECK ((credit_limit >= 0)),
    CONSTRAINT replay_vision_replayscanner_estimated_monthly_observation_check CHECK ((estimated_monthly_observations >= 0)),
    CONSTRAINT replay_vision_replayscanner_sweep_throttle_factor_overrid_check CHECK ((sweep_throttle_factor_override >= 0))
);


