    CONSTRAINT scout_config_enabled_matches_status CHECK (((enabled AND ((status)::text = ANY ((ARRAY['active'::character varying, 'pending_pause'::character varying])::text[]))) OR ((NOT enabled) AND ((status)::text = ANY ((ARRAY['paused_by_system'::character varying, 'paused_by_user'::character varying])::text[]))))),
    CONSTRAINT scout_config_pause_reason_matches_status CHECK ((((pause_reason IS NOT NULL) AND ((status)::text = ANY ((ARRAY['pending_pause'::character varying, 'paused_by_system'::character varying])::text[]))) OR ((pause_reason IS NULL) AND ((status)::text = ANY ((ARRAY['active'::character varying, 'paused_by_user'::character varying])::text[]))))),
    CONSTRAINT signals_signalscoutconfig_consecutive_failure_count_check CHECK ((consecutive_failure_count >= 0)),
    CONSTRAINT signals_signalscoutconfig_run_interval_minutes_check CHECK ((run_interval_minutes >= 0))
);


