    total_batches integer,
    total_rows bigint,
    sync_type character varying(32) NOT NULL,
    cumulative_row_count bigint DEFAULT 0 NOT NULL,
    resource_name character varying(400) NOT NULL,
    is_resume boolean DEFAULT false NOT NULL,
    is_first_ever_sync boolean DEFAULT false NOT NULL,
    metadata jsonb DEFAULT '{}'::jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    latest_state character varying(32) DEFAULT 'pending'::character varying NOT NULL,
    latest_attempt smallint DEFAULT 0 NOT NULL,
    state_changed_at timestamp with time zone,
    superseded boolean DEFAULT false NOT NULL
)
WITH (autovacuum_vacuum_scale_factor='0.02', autovacuum_analyze_scale_factor='0.02');


